    entryAppIds:[...s.entryAppIds], sourceQuestionMethodRaw:s.sourceQuestionMethodRaw,
    sourceQuestionMethodAudit:{type:"synonym_candidate_pool",normalizedCandidates:candidates,auditZh,mechanicalInterchangeability:false},
